'use strict';

const deepmerge = require('../utils/deep-merge');
const sessionExt = require('../utils/session-ext');

module.exports = function cacheRequestData (req, res, next) {

  if (!req.toBeCachedOnSession || !req.toBeCachedOnSession.user) {
    return next ();
  }
  if (req.session && req.session.user) {
    const toBeCachedOnSession = Object.assign({}, req.toBeCachedOnSession);
    sessionExt.update(req.session, function(session) {
      if (session) {
        // Preserve the pre-vendoring array-merge behaviour (keep existing items,
        // append new ones, never duplicate) so repeated caching neither grows nor
        // wipes arrays such as logout.destinations.
        session.user = deepmerge(session.user, toBeCachedOnSession.user, { arrayMerge: deepmerge.dedupeArrayMerge });
      }
    },()=>{
      delete req.toBeCachedOnSession;
      next();
    });
  } else {
    delete req.toBeCachedOnSession;
    next();
  }
};